import{z as i}from"zod";import{getPrdTemplate as y}from"./lib/snapshot.js";import{DEFAULT_PLATFORM as b}from"./lib/platforms.js";function w(s){const a=(s??"").trim().toLowerCase().replace(/[\s_-]/g,"");return["android","compose","kotlin","jetpackcompose","jdsandroid"].includes(a)?"android":["flutter","dart"].includes(a)?"flutter":["reactnative","native","rn","expo","ios","mobile"].includes(a)?"reactnative":["react","web","reactweb","nextjs","next"].includes(a)?"react":b}function I(s){s.registerPrompt("oneui-build-from-prd",{title:"Build a OneUI screen from a PRD",description:"Orchestrated, PLATFORM-BRANCHED workflow: given a product requirement and a target platform, call the OneUI MCP tools in the right order (load invariants \u2192 search knowledge \u2192 pick components \u2192 load brand \u2192 codegen/write TSX \u2192 validate \u2192 self-heal) and return a token-compliant, brand-correct, WCAG-AA component. The `platform` arg picks the runtime (@jds4/oneui-react web vs @oneui/ui-native), the scaffold/provider, the codegen path, and the validator rule-set. Invoke with /oneui-build-from-prd in Cursor, Claude Code, or any MCP-capable agent.",argsSchema:{prd:i.string().describe("The product or feature requirement. EITHER a short free-text description (a paragraph or two), OR a completed OneUI PRD template (from get_prd_template / oneui://prd-template). If you pass a filled template, its Brand & theme, Scope (v1 vs Deferred), Screens & flow, and Acceptance criteria sections drive the build."),platform:i.string().optional().describe('Target platform pack: "react" (web, @jds4/oneui-react \u2014 DEFAULT), "reactnative" (@oneui/ui-native), "android" (JDS Jetpack Compose), or "flutter" (Dart / package:ui_flutter). Aliases: native/rn/expo/ios/mobile \u2192 reactnative; web/next \u2192 react; compose/kotlin \u2192 android; dart \u2192 flutter. If the PRD names Compose / Jds* / create_oneui_android_app, pass "android". If it names OneUiSurface / ui_flutter / Flutter, pass "flutter". If it names SafeAreaView / ScrollView / React Native, pass "reactnative".'),brand:i.string().optional().describe('Target brand slug (default: "jio"). Available: jio, tira, reliance, swadesh, oneui-system. Call list_brands() to see all.'),route:i.string().optional().describe('Optional route or page context, e.g. "/checkout" or "ProfileScreen". Helps narrow component and layout decisions.')}},async({prd:n,platform:r,brand:l,route:c})=>{const t=l&&l.trim()?l.trim():"jio",e=w(r),o=e==="reactnative",m=e==="android",h=e==="flutter",d=c?`
Route / page context: **${c}**`:"";if(h)return{messages:[{role:"user",content:{type:"text",text:["# OneUI Flutter (Dart) build task","","## Requirement",n,d,"",`## Target brand: ${t}`,"## Target platform: Flutter (package:ui_flutter)","","---","","## Workflow \u2014 follow every step in order",'Pass `platform: "flutter"` to every tool that accepts it.',"","### Step 0 \u2014 Parse PRD","Obey \xA72 brand/theme, \xA73 v1 only, \xA74 screens, \xA78 acceptance. Do not invent Material chrome.","","### Step 1 \u2014 Invariants","Call `get_core_invariants()`. Flutter dialect: `OneUiSurface` for backgrounds, barrel import only, no hex/`Color(0x\u2026)`, no numeric EdgeInsets (token helpers OK).","","### Step 2 \u2014 Catalog",'`list_components({ platform: "flutter" })` + `get_component_info(name, "flutter")`. Catalog names are Figma-style (`Button`); emit `OneUiButton` from `package:ui_flutter/ui_flutter.dart`.','Load `get_skill_reference("figma-to-flutter", "references/widget-authoring.md")` and `references/avatar.md`.',"","### Step 3 \u2014 Brand",'`get_brand_tokens("'+t+'", true)`. Wrap the **app** in `OneUiBrandProvider` + `OneUiToastProvider` after `ensureOneUiBrandDefaultsLoaded()` and `JioIconCatalog.instance.ensureLoaded()`.',"","### Step 4 \u2014 Codegen",'**Path A \u2014 Figma in \xA76:** `figma_to_code({ url, platform: "flutter", codegen: true, brand: "'+t+'", outDir: "lib/screens" })` + skill figma-to-flutter.',"",'**Path B \u2014 text only:** Author a RefinedNode IR, then `codegen_from_ir({ tree, screenName, platform: "flutter", write: true, outDir: "lib/screens" })`.',"Node kinds: component | surface | node. Attention\u2192variant: high=bold, medium=subtle, low=ghost.","","### Step 5 \u2014 Validate",'`validate_oneui_code(code, "flutter")`. Self-heal barrel import, Material chrome, literals (up to 3 passes).',"","### Step 6 \u2014 Device verify (MANDATORY)","`flutter run` \u2192 screenshot \u2192 `verify_flutter_screen_loop` (cap 5). Clean validate alone is NOT done.","","### Step 7 \u2014 Return","Final `.dart` + summary: widgets used (`OneUi*`), surfaces, verify outcome."].join(`
`)}}]};if(m)return{messages:[{role:"user",content:{type:"text",text:["# OneUI / JDS Android (Compose) build task","","## Requirement",n,d,"",`## Target brand: ${t}`,"## Target platform: Android (JDS Jetpack Compose)","","---","","## Workflow \u2014 follow every step in order",'Pass `platform: "android"` to every tool that accepts it.',"","### Step 0 \u2014 Parse PRD","Obey \xA72 brand/theme, \xA73 v1 only (skip \xA73a), \xA74 screens, \xA78 acceptance. Mobile viewport = **360**.","If the PRD is a generic brief (no named OneUI components), run expand-prd first and wait for confirmation.","","### Step 1 \u2014 Invariants","Call `get_core_invariants()`. Android dialect: DimToken / Appearance / Surface \u2014 **never** literal dp/hex.","","### Step 2 \u2014 Foundations FIRST (mandatory before IR)",'1. `get_skill("build-with-tokens")` + `get_skill_reference("build-with-tokens", "references/android-tokens.md")` \u2014 **Dim4 = 16dp @360 default**.','2. `get_skill("oneui-design-composition")` + typography-scale + token-quick-reference.','3. `get_skill("surface")` / `surface-context`.','4. `get_skill("prd-to-android")` + `get_skill_reference("prd-to-android", "references/android-mvi-architecture.md")` + `references/ir-android.md`.',"   Architecture is MVI + Clean Architecture (ViewModel/Intent/UiState/UseCase/Repository/Hilt).",'5. `get_brand_tokens("'+t+'", true)`.',"","### Step 3 \u2014 Catalog",'`list_components({ platform: "android" })` + `get_component_info(name, "android")` for every planned component. Real props only.',"","### Step 4 \u2014 Codegen (screen UI)",'**Path A \u2014 Figma in \xA76:** `figma_to_code({ url, platform: "android", codegen: true, brand: "'+t+'" })` + skill figma-to-android.',"","**Path B \u2014 text/screenshot only:** DO NOT hand-author screen `.kt`. Author a RefinedNode IR tree, then:",'`codegen_from_ir({ tree, screenName, platform: "android", write: true })`.',"Node kinds: component | surface | node. Attention\u2192variant: high=bold, medium=subtle, low=ghost.","Images need `props.src`. See prd-to-android / ir-android for Login mapping.","","### Step 5 \u2014 MVI feature package (mandatory)","IR/Figma codegen emits **presentation Screen UI only**. Scaffold `feature/<name>/` per android-mvi-architecture:","presentation (Intent/Action/UiState/Effect/ViewModel + screen/), domain, data. Screen collects StateFlow;","never call Repository from Compose. Stub UseCases when \xA73a defers API; still keep interfaces.","","### Step 6 \u2014 Validate",'`validate_oneui_code(code, "android")`. Self-heal up to 3 passes (literal dp/hex, unknown props).',"","### Step 7 \u2014 Device verify (MANDATORY)","Host under FoundationTheme \u2192 `./gradlew installDebug` \u2192 adb screencap \u2192 compare PRD \xA76 (semantic) \u2192","`verify_android_screen_loop` (cap 5). Clean validate alone is NOT done.","","### Step 8 \u2014 Return","Final screen `.kt` + MVI feature files + summary: components, surfaces, DimToken/layout, architecture choices, verify outcome."].join(`
`)}}]};const k=o?"@oneui/ui-native":"@jds4/oneui-react",_=o?"OneUIBrandProvider":"BrandProvider",u=o?"React Native (@oneui/ui-native)":"React (web, @jds4/oneui-react)",f=["```tsx","import '@jds4/oneui-react/styles';","import '@jds4/oneui-icons-jio';","import { BrandProvider, Surface, /* components... */ } from '@jds4/oneui-react';","","export default function MyScreen() {","  return (",`    <BrandProvider brand="${t}">`,"      {/* layout + components here */}","    </BrandProvider>","  );","}","```"].join(`
`),g=["```tsx","import { SafeAreaView, ScrollView } from 'react-native';","import { OneUIBrandProvider } from '@oneui/ui-native/theme';","import { Icon } from '@oneui/ui-native/components/Icon';","import { Button } from '@oneui/ui-native/components/Button';  // one line per component","","export default function MyScreen() {","  return (",`    <OneUIBrandProvider brand="${t}" theme="${t}">`,"      <SafeAreaView style={{ flex: 1 }}>","        <ScrollView>{/* sections + components here */}</ScrollView>","      </SafeAreaView>","    </OneUIBrandProvider>","  );","}","```","`theme` = the sub-brand (e.g. jiomart / jionews); default to the brand slug if the PRD \xA72 gives none."].join(`
`),v=o?g:f;return{messages:[{role:"user",content:{type:"text",text:["# OneUI build task","","## Requirement",n,d,"",`## Target brand: ${t}`,`## Target platform: ${u}`,"","---","","## Your workflow \u2014 follow every step in order, do not skip",`Everything below is scoped to **${e}**. Pass \`platform: "${e}"\` to every`,"tool that accepts it (`list_components`, `get_component_info`, `figma_to_code`, `validate_oneui_code`).","","### Step 0 \u2014 If the requirement is a filled PRD template, parse it first",'If the requirement above is a completed OneUI PRD template (has sections like "## 2. Brand & theme",','"## 3. Scope", "## 4. Screens & flow"), extract and obey:',"  - **Brand & theme / mode** (\xA72): if it names a brand and no brand argument was given, use the","    template's brand instead of the default; note the theme + light/dark mode.","  - **Platform** (\xA74 components / \xA77 constraints): if the PRD calls for React Native (SafeAreaView,",'    ScrollView, "@oneui/ui-native", "single React Native component") but `platform` was passed as',`    "react", STOP and re-run this prompt with \`platform: "reactnative"\`. Current run is **${e}**.`,"  - **Scope v1 (\xA73)** is exactly what to build. **Deferred (\xA73a) \u2014 DO NOT build** (no validation,","    integrations, auth, error/empty states unless they are in \xA73). Do not over-build.","  - **Screens & flow (\xA74)**: build each screen and wire every primary action to its destination route","    in the stated order. **Data (\xA75)** = use the mock data given. **References (\xA76)** ground the layout.","  - **Acceptance criteria (\xA78)** are the stop condition for the self-heal (and, on native, verify) loop.","If it is a short free-text description instead, just proceed to Step 1.","","### Step 1 \u2014 Load the invariants (mandatory first step)","Call `get_core_invariants()` and read it in full.","These rules apply to every line of code you write:","- **Zero literals.** No hardcoded colours, px sizes, font sizes, weights, or spacing values.","- **Role-explicit typography tokens.** Use `--Body-M-FontSize`, `--Label-S-FontSize`, etc.","  Never `--Typography-Size-*` (legacy). Always pair font-size with a matching line-height token.","- **Font family via token, never a literal.** Never write a literal typeface like `'JioType Var'` or `'Inter'` \u2014 the token resolves per brand.","- **Surface wrapping.** Never set `background` / `backgroundColor` with a surface token on a raw "+(o?"`View`":"`div`")+".",'  Use `<Surface mode="...">` \u2014 child tokens auto-remap, components stay readable on any background.',"- **Focus / touch targets.** Interactive elements meet the a11y minimum (44\xD744 on native).","- **Shape.** Buttons default to `Shape-Pill`. Other interactive elements default to `Shape-2`.","","### Step 2 \u2014 Search relevant guidance",`Call \`search_design_system("${n.slice(0,80).replace(/"/g,"'")}")\` to surface relevant rules and patterns.`,'Always call `get_skill("oneui-design-composition")` \u2014 page/layout composition, component selection, typography, spacing.','Call `get_skill("surface")` to decide WHICH surface level each region earns (default-first, restraint).','Call `get_skill("surface-context")` for the surface token-remapping mechanics \u2014 the rule models break most often.','ALWAYS call `get_skill("oneui")` \u2014 on BOTH web AND reactnative \u2014 it owns component-API correctness. Its',"SKILL.md links per-component usage rules under `rules/*`; for EVERY component you will use, read the",'relevant rule via `get_skill_reference("oneui", "rules/<file>.md")`. These rules carry component-specific','nuance the component JSON does not \u2014 e.g. IconButton attention semantics (bare icon = `attention="low"`;',"`medium`/`high` draw a filled circle) + icon wiring live in `rules/appearance-vs-attention.md` and","`rules/icons-and-text.md`.",o?'On native, ALSO call `get_skill("figma-to-native")` \u2014 it owns the RN pipeline, Figma\u2192RN mapping + runtime-error fixes.':null,"","### Step 3 \u2014 Select and read every component you plan to use",`Call \`list_components({ platform: "${e}" })\` to see what is available on THIS platform.`,`For **each** component you plan to use, call \`get_component_info(name, "${e}")\` and read:`,"  - `compositionRules.requires` / `allows` / `forbids` \u2014 hard constraints, not suggestions.","  - `variantLogic` \u2014 which variant to use when.","  - `props` \u2014 exact names, types, and defaults. Do not invent props.",'  - `interactionBehavior` \u2014 how the component RESPONDS to hover / press / focus / keyboard / disabled, in plain English. Read it before hand-rolling any state styling, focus ring, or key handler: the component almost certainly already does it. `get_component_info(name, section: "interaction")` returns just this section.',o?'  Web-only components may not exist in @oneui/ui-native \u2014 resolve every "or"-listed choice in the PRD against what `list_components` actually returns for reactnative.':null,"","### Step 4 \u2014 Load brand tokens",`Call \`get_brand_tokens("${t}", true)\` to read its colour roles and font choices.`,"The `rolesOnly=true` flag strips the full 25-step palette and returns just the key role values.","","### Step 5 \u2014 Produce the TSX via the IR pipeline: input \u2192 IR (RefinedNode) \u2192 codegen \u2192 TSX","The One UI codegen pipeline is `frontend \u2192 IR (RefinedNode tree) \u2192 backend (codegen)`. You are the","frontend: turn the PRD (and any screenshot) into the RefinedNode IR, then let the deterministic","backend emit the TSX. This is fast (a tree-walk, no per-line authoring) and token-correct by","construction. Choose the path by what the PRD \xA76 (Visual references) provides:","","**Path A \u2014 Figma reference present (a figma.com URL with a node-id).**",`Run \`figma_to_code({ url, platform: "${e}", codegen: true, brand: "${t}" })\`.`,"That frontend does extract \u2192 refine \u2192 download assets \u2192 codegen for you. Continue to Step 6.","",...o?["**Path B \u2014 No Figma (plain text, screenshot, or both) \u2192 EMIT THE IR, then run the codegen backend.**","IR generation is YOUR job here (for Figma, figma_to_code does it; on this path you do). It works","from ANY of: (1) PRD plain text only, (2) a screenshot only, (3) text + screenshot. A screenshot is","optional grounding, never required \u2014 with plain text alone, infer the screens/sections/components/copy","from the PRD \xA74 description and author the tree directly.","a. Build a `RefinedNode` tree from the PRD \xA74 screens (and the \xA76 screenshot if one was given). Node kinds:",'   - `{ kind: "component", component, props?, text?, appearance?, children?, slots? }` \u2014 `component`',"     is a REAL @oneui/ui-native name from Step 3 (list_components / get_component_info). Put visible","     copy in `text`; map attention\u2192variant (high=bold, medium=subtle, low=ghost) in `props`.",'   - `{ kind: "surface", mode, children }` \u2014 every tinted/dark/coloured region. `mode` is one of',"     default/minimal/subtle/moderate/bold/elevated/ghost. Never paint a background any other way.",'   - `{ kind: "node", name, layout?, children }` \u2014 a plain structural container (rows/columns/sections).',"   Images: use a `component` image node with a placeholder `props.src` (no Figma asset download on","   this path \u2014 a src-less image warns + renders blank). Icons: use the icon component, never emoji \u2014","   and use one wherever the pattern calls for it (nav back/close/menu, a leading icon on typed list","   rows, a trailing chevron on rows that navigate deeper, a supporting icon on actions with an","   obvious glyph, semantic status icons) without decorating plain rows/labels that don't need one","   (see `rules/icons-and-text.md`).",'b. Call `codegen_from_ir({ tree, screenName, platform: "reactnative", write: true })`. It guards',"   the IR twice \u2014 structural schema, then a CATALOG check that every `component` name + its props","   are real (same data as get_component_info) \u2014 then runs the SAME backend figma_to_code uses and","   returns/writes the `.native.tsx`. Continue to Step 6 with that output.","If codegen_from_ir reports an unknown component or prop, fix it against get_component_info and re-emit","the IR \u2014 do NOT hand-write TSX unless a needed component genuinely has no @oneui/ui-native equivalent."]:["**Path B \u2014 No Figma (screenshots and/or text) \u2192 HAND-AUTHOR from the scaffold.**","The codegen backend is wired for reactnative only, so on web author the TSX directly against the",`${u} scaffold below, using the component APIs from Step 3:`,v,"Rules while writing:",'  - Every tinted/dark/coloured background is a `<Surface mode="...">`, not a raw `<div style={{ background }}>`.',"  - Use spacing/shape tokens, never px literals; route every font through a token; pair font-size with line-height.","  - Attention\u2192variant: high=bold, medium=subtle, low=ghost. Icons only via the icon component, never","    emoji \u2014 use one wherever the pattern calls for it (nav back/close/menu, a leading icon on typed","    list rows, a trailing chevron on rows that navigate deeper, a supporting icon on actions with an","    obvious glyph, semantic status icons) without decorating plain rows/labels that don't need one","    (see `rules/icons-and-text.md`)."],"","### Step 6 \u2014 Validate (platform rule-set)",`Call \`validate_oneui_code(tsx, "${e}")\` with the complete TSX. The "${e}" platform selects the correct rule-set `+(o?"(literal-color, hardcoded-font, external-icon-import, must-use-@oneui/ui-native, unknown-prop).":"(forbidden-base-ui, legacy-token, inline-surface-paint, unknown-prop)."),"","### Step 7 \u2014 Self-heal (up to 3 passes)","For each issue the validator returns, fix and re-run:",'  - `inline-surface-paint`: replace the inline background with a `<Surface mode="...">` wrapper.',"  - `legacy-token`: replace with the role-explicit token shown in the suggestion.","  - `literal-color` / `hardcoded-font` (native): replace with the token/role indicated.","  - `external-icon-import` (native): import the icon from `@oneui/ui-native` / the icons pack.","  - `unknown-prop`: remove the prop or rename it to the correct one from the component API.",`Re-run \`validate_oneui_code(tsx, "${e}")\` after each round. Stop when it returns "All clear".`,...o?["","### Step 8 (native only) \u2014 Verify on device: cross-check the provided screenshot (MANDATORY)","A clean validator is NOT a verified screen \u2014 it only proves the code compiles and uses no","banned APIs. This step closes the gap by comparing what actually renders against the reference","the user gave you. Do it for every screen you built; never declare done on the validator alone.","1. **Build & launch** \u2014 boot a simulator/emulator and `expo run:ios` / `expo run:android`,","   with the built screen set as the entry so it boots straight into it.","2. **Screenshot the OUTPUT** \u2014 capture the running screen:","   `xcrun simctl io booted screenshot /tmp/oneui-actual.png` (iOS) /","   `adb -s <device> exec-out screencap -p > /tmp/oneui-actual.png` (Android).","3. **Load the REFERENCE** \u2014 the screenshot the user provided in **PRD \xA76**, resolved to its","   file path and matched to the screen it maps to. (If \xA76 gives a Figma link instead, fetch","   that frame via the Figma MCP `get_screenshot`.) If \xA76 has no resolvable screenshot for this","   screen, say so explicitly and skip the compare \u2014 do not invent a reference.","4. **Compare** \u2014 read BOTH images and enumerate concrete mismatches. Judge SEMANTICALLY first:","   right sections + hierarchy, component choice, surface/attention treatment, colour-role","   resolution, spacing scale, typography, icons/images, clipping, scrims. A PRD screenshot is","   usually an approximate mock (a different app or a rough comp) \u2014 do NOT fail on pixel-exact","   diffs or device-chrome/safe-area differences; gate on whether the screen means the same thing.","5. **Fix & re-loop** \u2014 fix in the `.native.tsx` \u2192 re-run `validate_oneui_code` \u2192 rebuild \u2192","   re-screenshot \u2192 re-compare. Cap 5 iterations. If not converged, return NEEDS_HUMAN_INPUT with","   the specific remaining blockers (legitimate only after \u22653 distinct fix attempts: no reference","   available, a platform-incapable design feature, or a mismatch that has plateaued). Forbidden",'   blockers: device-dimension/safe-area offsets, minor icon-fidelity gaps, "it looks close enough".']:[],"",`### Step ${o?"9":"8"} \u2014 Return the result`,"Return the final validated TSX followed by a concise summary:",`  - Platform (${e}) and the codegen path taken (A: figma_to_code, or B: hand-authored).`,"  - Components chosen and why (variantLogic decision, attention level).","  - Surface modes applied and where.","  - Any brand-specific token or font overrides used.","  - Accessibility decisions (aria/accessibility labels, keyboard/focus, touch targets).",o?"  - Device-verify outcome (matched / NEEDS_HUMAN_INPUT + blockers).":null].filter(p=>p!==null).join(`
`)}}]}}),s.registerPrompt("oneui-prd",{title:"Start a OneUI PRD",description:"Drop the OneUI PRD template into the chat to fill in. Once completed, pass it to /oneui-build-from-prd to generate the screens (code), or /oneui-prd-to-figma for a Figma frame. Invoke with /oneui-prd.",argsSchema:{}},async()=>{const n=y();return{messages:[{role:"user",content:{type:"text",text:n?`Fill in the PRD template below, then either:
- \`/oneui-build-from-prd\` \u2014 generate code (\`platform\` = "react" | "reactnative" | "android")
- \`/oneui-prd-to-android\` \u2014 Android Compose shortcut (IR \u2192 codegen_from_ir)
- \`/oneui-prd-to-figma\` \u2014 recreate as a Figma frame on the temporary Untitled file

${n}`:"PRD template is not available in this snapshot (run `npm run build:snapshot`)."}}]}});const a="https://www.figma.com/design/Ors8Y9cGtm1J1YelpT0I51/Untitled";s.registerPrompt("oneui-prd-to-figma",{title:"Recreate a OneUI PRD as a Figma screen",description:"Orchestrated PRD \u2192 Figma workflow: read docs/prds/<name>.md (or <name>-web.md), place a 360 / 1280 / 1920-wide hug-height frame on the temporary Untitled file (Page 1, right of existing), set Theme range + brand Theme on the root (Theme \u2260 Appearance), build with real OneUI / Micropatterns components only, upload assets, apply figma-surface-cascade on tinted regions, return the frame URL and save docs/prds/refs/<name>-rebuild.png. Invoke with /oneui-prd-to-figma. For code from a PRD use /oneui-build-from-prd instead.",argsSchema:{prd:i.string().describe('Path to a filled PRD (e.g. "docs/prds/jiogames-home.md") OR the full PRD markdown body.'),targetFile:i.string().optional().describe(`Figma file URL to write into (default: ${a}). Place on Page 1 to the right of existing frames.`)}},async({prd:n,targetFile:r})=>{const l=r&&r.trim()?r.trim():a;return{messages:[{role:"user",content:{type:"text",text:["# OneUI PRD \u2192 Figma task","","## Requirement (PRD)",n,"",`## Target Figma file: ${l}`,"Place the new frame on **Page 1**, to the **right** of existing frames.","","---","","## Your workflow \u2014 follow every step; do not skip","",'1. **Load rules** \u2014 call `get_skill("prd-to-figma")` and obey it end-to-end. For tinted regions also call `get_skill("figma-surface-cascade")` and `get_skill("surface")`. Read Theme recipe from `get_skill_reference("figma-surface-cascade", "references/collection-ids.md")`.',"2. **Read the PRD** \u2014 if `prd` is a path under the workspace, read that file. Detect platform (mobile 360 vs web 1280/1920). Obey \xA73 scope (skip \xA73a Deferred), \xA74 section order + copy exactly, \xA76 for source assets / refs.","3. **Inspect target** \u2014 Figma MCP `get_metadata` on Page 1; place at `x = max(existing.x + width) + 80`.","4. **Assets** \u2014 download from PRD \xA76 Figma source and/or `docs/prds/refs/<name>.png`; `upload_assets` into the **target** file (source refs are often read-only).","5. **Create root frame** \u2014 width **360** (mobile) or **1280**/**1920** (web per PRD \xA72), vertical autolayout, `layoutSizingVertical = HUG`, name per platform.","5b. **Theme on root (mandatory \u2014 Theme \u2260 Appearance)** \u2014 immediately set `13.1 Theme range [Jio]` (`A\u2013M` / `N\u2013Z`) + `13.2`/`13.3` brand mode matching PRD theme (e.g. `JioMart`). Use `setExplicitVariableModeForCollection`. Verify `root.explicitVariableModes` has both. Do **not** substitute Appearance. Skipping this leaves default MyJio indigo.","5c. **Button Labels after Theme** \u2014 MyJio cascade pins (`primary.base=600`) make `tintedA11y` near-fill on other Themes (e.g. JioGames/JioFit). After Theme + Buttons, run `fixButtonLabelCascade(root)` from `figma-surface-cascade` (or let `applySurfaceCascade` auto-repair bold Button Labels).","6. **Build top \u2192 bottom** with **real OneUI / Micropatterns instances only** (HeaderNative / WebHeader, Carousel, Badge, Button, Image, Avatar, IconButton, BottomNav, PaginationDots, \u2026). No fake chrome, hex fills on surfaces, or hand-drawn carousel arrows/dots. Web: WebHeader PrimaryNav `\u26D4\uFE0F=1440|1920` + FILL to frame width.","7. **Tinted regions** (mini player, tinted cards) \u2014 bind `colour/surface/surface` + Appearance/Surface/parent-step modes via the surface-cascade skill. Never raw hex on interactive surfaces.","8. **Carousels** \u2014 real Carousel + PaginationDots only.","9. **Deliver** \u2014 return the frame URL (`?node-id=` with hyphens) and save a rebuild screenshot to `docs/prds/refs/<name>-rebuild.png` via `get_screenshot`. Confirm brand primary on chrome (e.g. JioMart cyan), not MyJio indigo.","","## Done when","- Frame matches PRD section order + copy","- Root Theme modes verified (`13.1` + `13.2`/`13.3`)","- Real components only; surfaces cascaded","- Frame URL + rebuild PNG delivered"].join(`
`)}}]}})}export{I as registerPrompts};
